mapper.select:
SELECT lr.*, pe.employee_name AS employeeName, pe.position, ps.store_name AS storeName, pa.employee_name AS approverName FROM attendance_leave_request lr LEFT JOIN pos_employee pe ON lr.employee_id = pe.id LEFT JOIN pos_store ps ON lr.store_id = ps.id LEFT JOIN pos_employee pa ON lr.approver_id = pa.id WHERE lr.deleted = 0 AND lr.tenant_id = #{tenantId}
AND lr.store_id IN #{sid}
AND (#{employeeId} IS NULL OR lr.employee_id = #{employeeId}) AND (#{status} IS NULL OR lr.status = #{status}) AND (#{startDate} IS NULL OR lr.start_date >= #{startDate}) AND (#{endDate} IS NULL OR lr.end_date <= #{endDate}) ORDER BY lr.create_time DESC
